head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > nextTabByEnter]<br/>컴포넌트에서 Enter 키 입력 시 포커스를 이동할지 여부를 설정합니다.",
    "validation" : [
        "nextTabID 가 설정되어 있지 않으면 nextTabByEnter 속성은 false 로 동작합니다."
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
      // 기존 target 있으면 삭제
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (startcomp)   
    let properties = {
        tabIndex : 1,             
    };

    // 조건 설정 (target)   
    let properties2 = {
        tabIndex : 2,
        // nextTabID: "startcomp",  
        nextTabByEnter: wf_sample.getObj("con_nextTabByEnter").getText(),
        enterBlur: wf_sample.getObj("con_enterBlur").getText(),
    };

    let cList = $c.gcm.createCList(properties);      
    let cList2 = $c.gcm.createCList(properties2);      

    $c.gcm.createBasicInput(cList, 'ev:onfocus="scwin.startcomp_onfocus"', 'startcomp');  
    $c.gcm.createBasicInput(cList2, 'ev:onfocus="scwin.target1_onfocus" ev:onblur="scwin.target1_onblur"');

    startcomp.setValue("start");
    target1.setValue("target");
}
